/// <summary>
/// This class used for extension of VendPackingSlipJournal.
/// </summary>
[ExtensionOf(formDataSourceStr(VendPackingSlipJournal, VendPackingSlipJour))]
internal final class METVendPackingSlipJournalFormDataSource_Extension
{
}

Method.Source:
/// <summary>
/// This is the COC method fro init method .
/// </summary>
public void init()
{
    next init();
    Args args = element.args();
    METItemInquiryHelper helper;
    FormRun callerForm = args.caller() as FormRun;

    if (element.args().parmObject())
    {
        helper                  = element.args().parmObject();
        ItemId                      itemIdFilter = helper.parmItemId();
        InventLocationId            inventLocationIdFilter = helper.parmInventLocationId();
        TransDate  lastMonthDate = systemDateGet() - 30;
        if (itemIdFilter || inventLocationIdFilter)
        {
            QueryBuildDataSource  qbdsLoc = this.queryBuildDataSource();
            qbdsLoc.clearRanges();
            qbdsLoc.addRange(fieldNum(PurchLineBackOrderWorkspace, DeliveryDate)).value(queryRange(lastMonthDate, systemDateGet()));

            QueryBuildDataSource    qbds1, qbds2;
            qbds1 = qbdsLoc.addDataSource(tableNum(VendPackingSlipTrans));
            qbds1.joinMode(JoinMode::InnerJoin);
            qbds1.addLink(fieldNum(VendPackingSlipJour, RecId), fieldNum(VendPackingSlipTrans, VendPackingSlipJour));
            qbds1.addRange(fieldNum(VendPackingSlipTrans, ItemId)).value(queryValue(itemIdFilter));
            qbds2 = qbdsLoc.addDataSource(tableNum(PurchTable));
            qbds2.joinMode(JoinMode::InnerJoin);
            qbds2.addLink(fieldNum(VendPackingSlipJour, PurchId), fieldNum(PurchTable, PurchId));
            qbds2.addRange(fieldNum(PurchTable, InventLocationId)).value(queryValue(inventLocationIdFilter));
        }
    }
}
